import{c as a,Q as t,j as s,m as n}from"./chunks/framework.DOi4mjdC.js";const u=JSON.parse('{"title":"GetReduceRepeatMaxMinSpr(ISASI)","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetReduceRepeatMaxMinSpr\\\\(ISASI\\\\)","slug":"getreducerepeatmaxminsprisasi"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/归约计算/GetReduceRepeatMaxMinSpr(ISASI).md","filePath":"api/SIMD-API/基础API/Memory矢量计算/归约计算/GetReduceRepeatMaxMinSpr(ISASI).md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/归约计算/GetReduceRepeatMaxMinSpr(ISASI).md"};function p(d,e,i,c,o,r){return t(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="getreducerepeatmaxminspr-isasi" tabindex="-1">GetReduceRepeatMaxMinSpr(ISASI) <a class="header-anchor" href="#getreducerepeatmaxminspr-isasi" aria-label="Permalink to &quot;GetReduceRepeatMaxMinSpr\\(ISASI\\)&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持（仅获取最值的原型）</th><th>是否支持（获取最值和索引的原型）</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>x</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>√</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>获取<a href="./ReduceMax.html">ReduceMax</a>、<a href="./ReduceMin.html">ReduceMin</a>连续场景下的最大/最小值以及相应的索引值。</p><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>获取<a href="./ReduceMax.html">ReduceMax</a>、<a href="./ReduceMin.html">ReduceMin</a>连续场景下的最大值与最小值，以及相应的索引值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetReduceRepeatMaxMinSpr(T &amp;maxMinValue, T &amp;maxMinIndex)</span></span></code></pre></div></li><li><p>获取<a href="./ReduceMax.html">ReduceMax</a>、<a href="./ReduceMin.html">ReduceMin</a>连续场景下的最大值与最小值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T&gt;</span></span>
<span class="line"><span>__aicore__ inline void GetReduceRepeatMaxMinSpr(T &amp;maxMinValue)</span></span></code></pre></div></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>ReduceMax/ReduceMin指令的数据类型，支持half/float。</td></tr></tbody></table><p><strong>表 2</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>maxMinValue</td><td>输出</td><td>ReduceMax/ReduceMin指令的最大值/最小值。</td></tr><tr><td>maxMinIndex</td><td>输出</td><td>ReduceMax/ReduceMin指令的最值对应的索引值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，由于ReduceMax/ReduceMin的内部实现原因，直接调用GetReduceRepeatMaxMinSpr接口无法获取到准确的索引值，验证时需要使用<a href="./WholeReduceMax.html">WholeReduceMax</a>/<a href="./WholeReduceMin.html">WholeReduceMin</a>接口来获取准确的索引值。</li><li>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，由于ReduceMax/ReduceMin的内部实现原因，直接调用GetReduceRepeatMaxMinSpr接口无法获取到准确的索引值，验证时需要使用<a href="./WholeReduceMax.html">WholeReduceMax</a>/<a href="./WholeReduceMin.html">WholeReduceMin</a>接口来获取准确的索引值。</li><li>针对Ascend 950PR/Ascend 950DT，由于ReduceMax/ReduceMin的内部实现原因，直接调用GetReduceRepeatMaxMinSpr接口无法获取到准确的索引值，验证时需要使用<a href="./WholeReduceMax.html">WholeReduceMax</a>/<a href="./WholeReduceMin.html">WholeReduceMin</a>接口来获取准确的索引值。同时，GetReduceRepeatMaxMinSpr必须紧跟着<a href="./WholeReduceMax.html">WholeReduceMax</a>/<a href="./WholeReduceMin.html">WholeReduceMin</a>接口进行调用。</li><li>索引maxMinIndex数据\`是按照ReduceMax/ReduceMin的数据类型进行存储的，比如ReduceMax/ReduceMin使用half类型时，maxMinIndex是按照half类型进行存储的，如果按照half格式进行读取，maxMinIndex的值是不对的，因此maxMinIndex的读取需要使用reinterpret_cast方法转换到整数类型，若输入数据类型是half，需要使用reinterpret_cast&lt;uint16_t*&gt;，若输入是float，需要使用reinterpret_cast&lt;uint32_t*&gt;。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>具体可参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/whole_reduce_min_max_sum" target="_blank" rel="noreferrer">WholeReduce系列归约指令样例</a>。</p><ol><li><p>以ReduceMax指令为例，首先执行ReduceMax指令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;float&gt; src;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; work;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; dst;</span></span>
<span class="line"><span>int32_t mask = 64;</span></span>
<span class="line"><span>AscendC::ReduceMax(dst, src, work, mask, 1, 8, true); // 连续场景，srcRepStride = 8，且calIndex = true</span></span></code></pre></div></li><li><p>获取上述ReduceMax指令的最值与索引值。</p><p>针对Atlas A2 训练系列产品/Atlas A2 推理系列产品，需要使用WholeReduceMax指令获取准确的索引值，然后再调用GetReduceRepeatMaxMinSpr指令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;float&gt; src;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; dst;</span></span>
<span class="line"><span>int32_t mask = 64;</span></span>
<span class="line"><span>AscendC::WholeReduceMax(dst, src, mask, 1, 1, 1, 8);</span></span>
<span class="line"><span>float val = 0;   // 最大值</span></span>
<span class="line"><span>float idx = 0;   // 最大值的索引值，与ReduceMax的结果相同，保证和WholeReduceMax的调动次序，而且要配对调用</span></span>
<span class="line"><span>AscendC::GetReduceRepeatMaxMinSpr&lt;float&gt;(val, idx);</span></span></code></pre></div><p>针对Atlas A3 训练系列产品/Atlas A3 推理系列产品，需要使用WholeReduceMax指令获取准确的索引值，然后再调用GetReduceRepeatMaxMinSpr指令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;float&gt; src;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; dst;</span></span>
<span class="line"><span>int32_t mask = 64;</span></span>
<span class="line"><span>AscendC::WholeReduceMax(dst, src, mask, 1, 1, 1, 8);</span></span>
<span class="line"><span>float val = 0;   // 最大值</span></span>
<span class="line"><span>float idx = 0;   // 最大值的索引值，与ReduceMax的结果相同，保证和WholeReduceMax的调动次序，而且要配对调用</span></span>
<span class="line"><span>AscendC::GetReduceRepeatMaxMinSpr&lt;float&gt;(val, idx);</span></span></code></pre></div><p>针对Atlas 推理系列产品AI Core版本，则可在调用ReduceMax后直接调用GetReduceRepeatMaxMinSpr指令获取其最大/最小值。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;float&gt; src;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; work;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; dst;</span></span>
<span class="line"><span>int32_t mask = 64;</span></span>
<span class="line"><span>AscendC::ReduceMax(dst, src, work, mask, 1, 8, true);</span></span>
<span class="line"><span>float val = 0;   // 最大值</span></span>
<span class="line"><span>AscendC::GetReduceRepeatMaxMinSpr&lt;float&gt;(val); // 保证和WholeReduceMax的调动次序，而且要配对调用</span></span></code></pre></div><p>针对Ascend 950PR/Ascend 950DT，需要先执行WholeReduceMax指令，随后立即调用GetReduceRepeatMaxMinSpr指令。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>AscendC::LocalTensor&lt;float&gt; src;</span></span>
<span class="line"><span>AscendC::LocalTensor&lt;float&gt; dst;</span></span>
<span class="line"><span>int32_t mask = 64;</span></span>
<span class="line"><span>float val = 0;   // 最大值</span></span>
<span class="line"><span>float idx = 0;   // 最大值的索引值，与ReduceMax的结果相同</span></span>
<span class="line"><span>AscendC::WholeReduceMax(dst, src, mask, 1, 1, 1, 8);</span></span>
<span class="line"><span>AscendC::GetReduceRepeatMaxMinSpr&lt;float&gt;(val, idx); // 保证和WholeReduceMax的调动次序，而且要配对调用</span></span></code></pre></div></li></ol>`,19)])])}const M=a(l,[["render",p]]);export{u as __pageData,M as default};
